  public void structFromBuilderSerializeDeserialize() throws Exception {
    ImmutableStructFromBuilder structFromBuilder = ImmutableStructFromBuilder.builder()
        .a(1)
        .os(true)
        .array(true, false)
        .addBag("a")
        .addC("c", "d")
